sys_variable_value.value:
/**
 * Guarantees the case_type / risk appropriate investigation task set exists.
 * Idempotent - existing non-cancelled tasks of the same type are left alone.
 */
(function execute(inputs, outputs) {
    outputs.taskCount = new bfd_FlowSupport().ensureInvestigationTasks(inputs.caseSysId);
})(inputs, outputs);

